<?php require_once __DIR__.'/../includes/config.php'; require_once __DIR__.'/../includes/database.php'; require_once __DIR__.'/../includes/auth.php'; require_once __DIR__.'/../includes/csrf.php'; require_once __DIR__.'/../includes/functions.php'; if ($_SERVER['REQUEST_METHOD']!=='POST') redirect('register.php'); verify_csrf(); $name=trim($_POST['name']??''); $email=filter_var($_POST['email']??'',FILTER_VALIDATE_EMAIL); $password=$_POST['password']??''; if(!$email||strlen($name)<2||strlen($password)<8){flash('error','Completa los datos correctamente.');redirect('register.php');} try{$stmt=db()->prepare('INSERT INTO users(name,email,password,role) VALUES(?,?,?,?)');$stmt->execute([$name,$email,password_hash($password,PASSWORD_DEFAULT),'customer']);$u=['id'=>db()->lastInsertId(),'name'=>$name,'email'=>$email,'role'=>'customer'];login_user($u);redirect('dashboard.php');}catch(PDOException $e){flash('error','No fue posible crear la cuenta.');redirect('register.php');}
